TLM.f("Sancti/10-07",{"officium":"Sanctissimi Rosarii Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Festivitate;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis: de cujus sollemnitáte gaudent Angeli et colláudant Fílium Dei."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre beátæ Maríæ Vírginis: de cujus sollemnitáte gaudent Angeli et colláudant Fílium Dei."}],"Oratio":[{"k":"text","la":"Deus, cujus Unigénitus per vitam, mortem et resurrectiónem suam nobis salútis ætérnæ præmia comparávit: concéde, quǽsumus; ut, hæc mystéria sacratíssimo beátæ Maríæ Vírginis Rosário recoléntes, et imitémur, quod cóntinent, et quod promíttunt, assequámur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"rubric","la":"Prov 8:22-24; 8:32-35"},{"k":"text","la":"Dóminus possédit me in inítio viárum suárum, ántequam quidquam fáceret a princípio. Ab ætérno ordináta sum et ex antíquis, ántequam terra fíeret. Nondum erant abýssi, et ego jam concépta eram. Nunc ergo, fílii, audíte me: Beáti, qui custódiunt vias meas. Audíte disciplínam, et estóte sapiéntes, et nolíte abjícere eam. Beátus homo, qui audit me et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Qui me invénerit, invéniet vitam et háuriet salútem a Dómino."}],"Graduale":[{"k":"ref","la":"Ps 44:5; 44:11; 44:12"},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam, et dedúcet te mirabíliter déxtera tua."},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Sollémnitas gloriósæ Vírginis Maríæ ex sémine Abrahæ, ortæ de tribu Juda, clara ex stirpe David. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:26-38"},{"k":"text","la":"In illo témpore: Missus est Angelus Gábriel a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Quæ cum audísset, turbáta est in sermóne ejus: et cogitábat, qualis esset ista salutátio. Et ait Angelus ei: Ne tímeas, María, invenísti enim grátiam apud Deum: ecce, concípies in útero et páries fílium, et vocábis nomen ejus Jesum. Hic erit magnus, et Fílius Altíssimi vocábitur, et dabit illi Dóminus Deus sedem David, patris ejus: et regnábit in domo Jacob in ætérnum, et regni ejus non erit finis. Dixit autem María ad Angelum: Quómodo fiet istud, quóniam virum non cognósco? Et respóndens Angelus, dixit ei: Spíritus Sanctus supervéniet in te, et virtus Altíssimi obumbrábit tibi. Ideóque et quod nascétur ex te Sanctum, vocábitur Fílius Dei. Et ecce, Elisabeth, cognáta tua, et ipsa concépit fílium in senectúte sua: et hic mensis sextus est illi, quæ vocátur stérilis: quia non erit impossíbile apud Deum omne verbum. Dixit autem María: Ecce ancílla Dómini, fiat mihi secúndum verbum tuum."}],"Offertorium":[{"k":"ref","la":"Eccli 24:25; Eccli 39:17"},{"k":"text","la":"In me grátia omnis viæ et veritátis, in me omnis spes vitæ et virtútis: ego quasi rosa plantáta super rivos aquárum fructificávi."}],"Secreta":[{"k":"text","la":"Fac nos, quǽsumus, Dómine, his munéribus offeréndis conveniénter aptári: et per sacratíssimi Rosárii mystéria sic vitam, passiónem et glóriam Unigéniti tui recólere; ut ejus digni promissiónibus efficiámur:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Eccli 39:19"},{"k":"text","la":"Floréte, flores, quasi lílium, et date odórem, et frondéte in grátiam, collaudáte cánticum, et benedícite Dóminum in opéribus suis."}],"Postcommunio":[{"k":"text","la":"Sanctíssimae Genetrícis tuae, cuius Rosárium celebrámus, quaésumus, Dómine, précibus adiuvémur: ut et mysteriórum, quae cólimus, virtus percipiátur; et sacramentórum, quae súmpsimus, obtineátur efféctus:"},{"k":"macro","name":"Qui vivis"}],"Rank1960":[{"k":"text","la":"Festum Beatae Mariae Virginis a Rosario;;Duplex 2 classis;;5;;ex C11"}]},"hr":{"ea506bf5ff6ce5da":{"t":"Ps 44, 2\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije, čijoj se svetkovini raduju anđeli i hvale Sina Božjega. (Ps 44, 2). Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nRadujmo se svi u Gospodinu slaveći blagdan na čast blažene Djevice Marije, čijoj se svetkovini raduju anđeli i hvale Sina Božjega.","kn":", Radujmo se svi u Gospodinu svetkujući blagdan na čast blažene Djevice Marije, radi koje blagdana raduju se anđeli i hvale Sina Božjega (Ps. 44.) Iz mog Srca izvire divna pjesma: djela su moja namijenjena kralju. Slava Ocu . . , Radujmo se . . .","knRef":"Kniewald 1942, str. 728–729 (snimka 365) (OCR)"},"e5215e7ff3e14804":{"t":"<i>Pomolimo se</i>.\nBože, kojega je jedinorođeni Sin svojim životom, smrću i uskrsnućem dare nam pripravio vječnoga spasenja, podaj, molimo, da mi, koji ova otajstva svetim Ružarijem blažene Djevice Marije razmišljamo, ugledamo se u ono što sadržavaju, a postignemo ono što obećavaju.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, kojega nam je Jedinac životom, smrću i uskrsnućem svojim stekao plaće vječnoga života podaj, molimo, da promišljajući ta otajstva u presvetoj krunici blažene Djev.ice Marije , i nasljedujemo, što u sebi kriju i dostignemo, što obećavaju, po istom G. n.","knRef":"Kniewald 1942, str. 728–729 (snimka 365) (OCR)"},"19ca2930ddc58839":{"t":"Izr 8, 22-24 i 32-35\nČitanje Knjige Mudrosti: Gospodin me je imao u početku svojih putova, prije nego je išta učinio. Bila sam oduvijek određena, prije postanka zemlje. Još nije bilo bezdana, a ja sam već bila začeta. Zato me, djeco, čujte! Blago onima koji idu mojim putovima. Slušajte nauku, budite mudri, nemojte je odbaciti. Blago čovjeku koji mene sluša i koji svaki dan bdije uz moja vrata i čuva ulaze u moj dom. Tko mene nađe naći će život i primit će spasenje od Gospodina.","kn":"Čitanje knjige Mudrosti (Posl. 8, Ž2-24. 32-35), Gpspodin me je imao; u početku svojih puteva, prije nego je išta ućinip. na početku. Bila sam određena od vijeka i od davnina prije nego je postalazemlja. Još nije bilo bezdana, a ja sam veo bila začeta zato me, djeco, poslušajte: Blago oiiima, koji idu mojim putovima! Slušajte moju nauku i budite mudri i nemojte je odbaciti, .Blago.' čovjeku, koji me sluša i koji. uvijek bdije uz, moja. vrata i čdva ulaze u; moju kuću. :Tko nađe mene, naći ce život i primit će spas od Gospod-ina!","knRef":"Kniewald 1942, str. 728–729 (snimka 365) (OCR)"},"cbc4b80a2b5afb29":{"t":"Ps 44, 5 i 11 i 12\nRadi istine i krotkosti i pravde vodit će te divno tvoja desnica. Čuj, kćeri, i pogledaj, i prikloni svoje uho, jer je Kralju omiljela tvoja ljepota.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSvečanost slavne Djevice Marije, iz potomstva Abrahamova, rođene iz plemena Judina, iz slavnog roda Davidova. <i>Aleluja</i>.","kn":"(Ps. 44, 5, 11, 2). Istine radi i krotkosti i pravde vodit će te divno deisnica tvoja. Slušaj, kćeri, gledaj 1 prlgni uho svoje, jer omilje Kralju ljepota tvoja.\n\nAleluja, alelujaj Svečanost slavne Djevice Marije, iz - potomstva. Abrahamova, rođene iz koljena Judina, ,iz slavnog, roda Dayidova. Ale- luja.: - . -","knRef":"Kniewald 1942, str. 680–681 (snimka 341) (OCR)"},"b7fcb7fcf7056bff":{"t":"Lk 1, 26-38\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici Mariji, koja je bila zaručena s Davidovim potomkom Josipom. Anđeo uđe k njoj i reče: Zdravo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se i razmišljala je što taj pozdrav znači. Anđeo joj reče: Nemoj se bojati, Marijo, jer si našla milost u Boga: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. Gospodin će mu dati prijestolje njegova oca Davida, i vladat će Jakovljevom kućom dovijeka i njegovu kraljevstvu neće biti svršetka. Marija reče anđelu: Kako će to biti kad ne poznam muža? Anđeo joj odgovori: Duh će Sveti sići na te i sila će te Svevišnjega osjeniti. Zato će se ono Sveto, što ćeš ti roditi, zvati Sin Božji. A evo, i Elizabeta, tvoja rođakinja, i ona je začela sina u svojoj starosti, i njoj koju zovu nerotkinjom ovo je šesti mjesec, jer u Boga nije ništa nemoguće. Marija na to reče: Evo službenice Gospodnje, neka mi bude po riječi tvojoj.","kn":"t Slijedi sveto evanđelje po Luki (1, 26-38). U ono vrijeme posla Bog anđela Gabrijela u galilejski grad Nazaret k djevici zaručenoj s mužem, koji se zvaO' Josip iz kuće Davidove, a djevica se zvala Marija. Kad je anđeo k njoj ušao, reče: Zdravo milosti puna. Gospodin s tobom, blagoslovljena ti među ženama! Kad je ona to čula, uplaši se na ove riječi i razmišljala je, što znači taj pozdrav. A anđeo joj reče; Ne boj se, Marijo, jer si našla milost kod Bega: Evo, začet ćeš i roditi sina i dat ćeš mu ime Isus. On će biti velik i zvat će se Sin Svevišnjega. I Gospodin Bog dat će mu prijestolje Davida, njegova oca, i vladat će nad Jakovljevim domom u vijeke, i njegovu kraljevstvu ne će biti kraja. Marija upita anđela: Kako će to biti, kad ja ne (poznam muža? Anđeo joj odgovori: Duh Sveti doći će nad tebe i osjenit će te sila Svevišnjega; zato će i Sveto, koje ćeš ti roditi, biti Sin Božji. I tvoja je rođakinja Elizabeta začela Sv. Ivan Damascenski 27. III. sina u svojoj starosti, i njoj, koja je nerotkinja, ovo je šesti mjesec; jer Bogu nije ništa nemoguće. Na to Marija reče: Evo službenice Gospodnje, neka mi bude po tvojoj riječi.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"31a482c05c38b4bf":{"t":"Sir 24, 25; 39,17\nU meni je sva milost puta i istine, u meni je sva nada života i kreposti; izrasla sam kao ruža zasađena uz potoke voda.","kn":"(Crkv:'24, 25). U meni-je milost svakoga puta i istine, u meni' je svako ufanje života 1 kre posti; rodih rod, kao ruža zasađena uz potoke voda.","knRef":"Kniewald 1942, str. 728–729 (snimka 365) (OCR)"},"df7abe205a329fe1":{"t":"Daj, Gospodine, da na dostojan način postanemo prikladni za prinošenje ovih darova i da se otajstvima Ružarija tako spominjemo života, smrti i slave tvoga Jedinorođenoga te postanemo vrijedni njegovih obećanja:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"“Daj, Gospodine, da na dostojan' način posta, nemo prikladni za prinošenje ovihdarova . i da se ptajstvima ' krunice tako spominjemo, života. smrti i slave Jedinorođenoga Tvoga, te postanemo vrijedni njefgovih obećanja, koji s Tobom živi i kraljuje ...","knRef":"Kniewald 1942, str. 728–729 (snimka 365) (OCR)"},"006ab57f0d571d6b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o svetkovini</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"e28b9179646924e5":{"t":"Sir 39, 19\nCvati, cvijeće, kao ljiljan i daj miris, zeleni se miljem, pjevaj pjesmu hvale i blagoslivljaj Gospodina u njegovim djelima.","kn":"(Crkv. 39, 19). Cvatij cvijeće, kao ljiljan i daj. miris, zeleni se miljem, poj pjesmu hvale i blagosiljaj Gospodina u djelima njegovim.","knRef":"Kniewald 1942, str. 730–731 (snimka 366) (OCR)"},"ebd09532730d640b":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nađemo pomoć po zagovoru tvoje svete Majke, čiju svetkovinu Ružarija slavimo te budemo dionici kreposti otajstva što ih razmatramo i dostignemo plod svetih tajna što ih primamo:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, da nađemo pomoć po zagovoru Tvoje svete Majke, koje krunicu slavimo, te budemo dionici kreposti otajstva, što ih razmatramo i dostlgnemo plod svetih tajna, što' ih primamo; koji živiš ...","knRef":"Kniewald 1942, str. 730–731 (snimka 366) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
